style.css:
@-moz-document domain("ixl.com") {
html, body {
    background: linear-gradient(135deg, #f3f0ff, #e0f7fa, #fff9e6, #f5eaff) !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #4b3a57 !important;
  }

  .main-content, .content-area, .page-container {
    background-color: #f7f4fc !important;
    padding: 30px !important;
    border-radius: 25px !important;
    box-shadow: 0 6px 18px rgba(90, 74, 110, 0.2);
    width: 90% !important;
    margin: auto !important;
  }

  /* ? HOT PINK headers */
  h1, h2, h3, h4, h5, h6 {
    color: #ff1493 !important; /* hot pink */
  }

  /* ? HOT PINK buttons */
  button, .btn {
    background-color: #ff1493 !important;
    color: white !important;
    border: none !important;
    border-radius: 15px !important;
    padding: 12px 24px !important;
    font-weight: 700 !important;
    cursor: pointer !important;
    box-shadow: 0 5px 12px rgba(255, 20, 147, 0.5);
    transition: background-color 0.3s ease;
  }

  button:hover, .btn:hover {
    background-color: #e60073 !important; /* deeper hot pink */
  }

  /* ? Sky blue links */
  a {
    color: #7ec8e3 !important;
  }

  /* Lavender side panels */
  .sidebar, .right-sidebar, .panel, .widget {
    background-color: #ebe3fa !important;
    border-radius: 20px !important;
  }

  /* Pastel input fields */
  input, select, textarea {
    background-color: #f8f0fa !important;
    color: #4b3a57 !important;
    border: 1px solid #e3b2d1 !important;
    border-radius: 10px !important;
    padding: 8px !important;
  }

  /* Code boxes */
  pre, code, .code-block {
    background-color: #f0e6fc !important;
    color: #4b3a57 !important;
    border-radius: 12px !important;
    padding: 12px !important;
  }

  /* Soft border tables */
  table, th, td {
    border: 1px solid #e3ccee !important;
  }

  /* Images with a soft filter */
  img {
    filter: brightness(1.07) saturate(0.85);
    border-radius: 12px !important;
  }
}
